// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;

    function setUp() public {
        c = new airPort();
    }

    function testFuzz_property(uint256 len, uint256 v) public {
        len = bound(len, 1, 20);

        address from = address(0xF00D);
        Recorder rec = new Recorder();

        address[] memory tos = new address[](len);
        for (uint256 i = 0; i < len; i++) {
            tos[i] = address(uint160(0x1000 + i));
        }

        bool ok;
        try c.transfer(from, address(rec), tos, v) returns (bool r) {
            ok = r;
        } catch {
            ok = false;
        }

        // The reference always succeeds and records exactly one call per recipient.
        assertTrue(ok && rec.count() == len);
    }
}

contract Recorder {
    uint256 public count;

    function transferFrom(address, address, uint256) external returns (bool) {
        count++;
        return true;
    }
}
